function getPath(obj, path){
  return path.split('.').reduce((o,k)=> (o ? o[k] : undefined), obj);
}

function renderStatic(lang){
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key = el.getAttribute('data-i18n');
    const val = getPath(translations[lang], key);
    if(typeof val === 'string') el.textContent = val;
  });
  document.documentElement.lang = lang;
  try{localStorage.setItem('hs-lang', lang);}catch(e){}
}

function renderValues(lang){
  const row = document.getElementById('values-row');
  row.innerHTML = '';
  translations[lang].values.forEach(v=>{
    const div = document.createElement('div');
    div.className = 'value-card';
    div.innerHTML = `<h3>${v.title}</h3><p>${v.desc}</p>`;
    row.appendChild(div);
  });
}

