const SERVICE_POS = {laser:'center', electro:'center', peeling:'center', massage:'center', cosmetology:'center', cosmetics:'center', _default:'center'};

function renderServices(lang){
  const grid = document.getElementById('services-grid');
  grid.innerHTML = '';
  const items = translations[lang].services.items;
  const keys = currentCountry ? servicesByCountry[currentCountry] : Object.keys(items);
  const p = translations[lang].services.pricing;
  keys.forEach((key,i)=>{
    const s = items[key];
    if(!s) return;
    const div = document.createElement('div');
    div.className = 's-card';
    const sv = translations[lang].services;
    let priceBlock;
    if(key === 'laser'){
      priceBlock = `<div class="s-card-btns">
        <button class="s-btn-price price-link" data-price-type="laser">${sv.priceBtn}</button>
        <button class="s-btn-detail" data-laser-detail="1">${sv.detailBtnLabel}</button>
      </div>`;
    } else if(PRICED_SERVICES[key]||key==='trichology'){
      const detBtn = (typeof SERVICE_PAGES!=='undefined' && SERVICE_PAGES[key]) ? `<button class="s-btn-detail" data-service-detail="${key}">${sv.detailBtnLabel}</button>` : `<a class="s-btn-detail" href="https://www.instagram.com/hi.sisters_cz/" target="_blank" rel="noopener">${sv.detailBtnLabel}</a>`;
      priceBlock = `<div class="s-card-btns">
        <button class="s-btn-price price-link" data-price-type="${PRICED_SERVICES[key]}">${sv.priceBtn}</button>
        ${detBtn}
      </div>`;
    } else if(typeof SERVICE_PAGES!=='undefined' && SERVICE_PAGES[key]){
      priceBlock = `<div class="s-card-btns">
        <button class="s-btn-detail s-btn-detail-solo" data-service-detail="${key}">${sv.detailBtnLabel}</button>
      </div>`;
    } else {
      priceBlock = `<div class="price">${sv.priceNote}</div>`;
    }
    const grad = SERVICE_GRADIENTS[key] || SERVICE_GRADIENTS._default;
    const pos = SERVICE_POS[key] || SERVICE_POS._default;
    const bgStyle = (serviceImages[key] ? `background-image:url('${serviceImages[key]}')` : `background-image:${grad}`) + `;background-position:${pos}`;
    div.innerHTML = `
      <div class="s-card-media" style="${bgStyle}"></div>
      <div class="s-card-inner">
        <span class="num">0${i+1}</span>
        <h3>${s.title}</h3>
        <p>${s.desc}</p>
        ${priceBlock}
      </div>`;
    grid.appendChild(div);
  });
}

/* ---- Cart state ---- */
let cart = (function(){try{return JSON.parse(localStorage.getItem('hs-cart'))||[]}catch(e){return []}})(); // survives page changes
const CONTACT_NUMBER = '420702192946';

/* ---- Order forwarding to manager (Cloudflare Worker → Telegram bot) ----
   Paste your deployed Worker URL below. While empty, nothing is sent and the
   normal WhatsApp/Telegram hand-off keeps working unchanged.
   Example: 'https://hi-sisters-orders.anna.workers.dev'                       */
const ORDER_WEBHOOK = '';

function collectOrder(lang, channel){
  return {
    items: cart.map(i=>({title:i.title, price:i.price, czk:i.czk, eur:i.eur})),
    total: cartTotal(),
    totalText: cartTotalText(),
    lang, channel,
    country: currentCountry || null,
    name: (document.getElementById('cart-name')?.value || '').trim(),
    contact: (document.getElementById('cart-contact')?.value || '').trim(),
    page: location.href,
    ts: new Date().toISOString()
  };
}

function notifyManager(lang, channel){
  if(!ORDER_WEBHOOK || !cart.length) return;
  try{
    fetch(ORDER_WEBHOOK, {
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify(collectOrder(lang, channel)),
      keepalive: true
    }).catch(()=>{});
  }catch(e){}
}

/* Course prices read "25 000 Kc / 1 000 EUR"; one course is priced on request.
   parseInt() stopped at the first space and turned 25 000 Kc into 25 EUR. */
function parsePrice(raw){
  const s = String(raw || '');
  const num = re => { const m = s.match(re); return m ? parseInt(m[1].replace(/[\s\u00a0]/g,''), 10) : null; };
  return { raw: s, czk: num(/([\d\s\u00a0]+)K\u010d/), eur: num(/([\d\s\u00a0]+)\u20ac/) };
}
function fmtNum(n){ return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '\u00a0'); }
function cartTotal(){
  return cart.reduce((a,i)=>({czk:a.czk+(i.czk||0), eur:a.eur+(i.eur||0), priced:a.priced+((i.czk||i.eur)?1:0)}),
                     {czk:0, eur:0, priced:0});
}
function cartTotalText(){
  const t = cartTotal();
  if(!t.priced) return '\u2014';
  const parts = [];
  if(t.czk) parts.push(fmtNum(t.czk) + '\u00a0K\u010d');
  if(t.eur) parts.push(fmtNum(t.eur) + '\u00a0\u20ac');
  return parts.join(' / ');
}

function cartIncludes(id){ return cart.some(i=>i.id===id); }

function cartAdd(id, title, price){
  const p = parsePrice(price);
  if(!cartIncludes(id)) cart.push({id, title, price: p.raw, czk: p.czk, eur: p.eur});
  renderCartDrawer(currentLang);
  updateCartBadge();
  updateTrainingButtons(currentLang);
}

function cartRemove(id){
  cart = cart.filter(i=>i.id!==id);
  renderCartDrawer(currentLang);
  updateCartBadge();
  updateTrainingButtons(currentLang);
}

function updateCartBadge(){
  try{localStorage.setItem('hs-cart', JSON.stringify(cart));}catch(e){}
  const badge = document.getElementById('cart-badge');
  badge.textContent = cart.length;
  badge.style.display = cart.length ? 'flex' : 'none';
}

/* Labels are built here rather than taken from translations[lang].cart: a later
   patch overwrites that object, and in the second version msgTotal/msgQuestion
   lost their line breaks and msgQuestion turned into a bare "Kontakt:" label.
   Reading them produced a run-together message ending in a colon with nothing
   after it — and the name/phone the client typed were never included at all. */
const ORDER_LABELS = {
  cs:{name:'Jméno', contact:'Kontakt', total:'Celkem'},
  ru:{name:'Имя', contact:'Контакт', total:'Итого'},
  uk:{name:'Імʼя', contact:'Контакт', total:'Разом'},
  en:{name:'Name', contact:'Contact', total:'Total'},
  es:{name:'Nombre', contact:'Contacto', total:'Total'}
};

function buildOrderMessage(lang){
  const c = translations[lang].cart;
  const L = ORDER_LABELS[lang] || ORDER_LABELS.en;
  const val = id => ((document.getElementById(id)||{}).value || '').trim();
  let msg = String(c.msgGreeting || '').trim() + '\n\n';
  cart.forEach(i=>{ msg += `• ${i.title} — ${i.price}\n`; });
  msg += `\n${L.total}: ${cartTotalText()}`;
  const nm = val('cart-name'), ct = val('cart-contact');
  if(nm) msg += `\n${L.name}: ${nm}`;
  if(ct) msg += `\n${L.contact}: ${ct}`;
  return msg;
}

/* The WhatsApp href is built when the drawer renders — i.e. before the client
   has typed anything. Rebuild it on click so what they typed actually goes. */
function refreshOrderLinks(){
  try{
    const wa = document.getElementById('cart-wa-btn');
    if(wa) wa.href = `https://wa.me/${CONTACT_NUMBER}?text=${encodeURIComponent(buildOrderMessage(currentLang))}`;
  }catch(e){}
}

function openCart(){
  document.getElementById('cart-drawer').classList.add('open');
  document.getElementById('cart-overlay').classList.add('open');
}
function closeCart(){
  document.getElementById('cart-drawer').classList.remove('open');
  document.getElementById('cart-overlay').classList.remove('open');
}

/* The later translation patch replaces whole sections with Object.assign, so
   keys the patch does not repeat are dropped. cart.title is one of them — the
   drawer opened with a blank header. And #cart-total-label-text was never
   written from JS at all, so the total stayed the English "Total" everywhere. */
const CART_FALLBACK = {
  cs:{title:'Košík', total:'Celkem'},
  ru:{title:'Корзина', total:'Итого'},
  uk:{title:'Кошик', total:'Разом'},
  en:{title:'Cart', total:'Total'},
  es:{title:'Carrito', total:'Total'}
};

function renderCartDrawer(lang){
  const c = translations[lang].cart;
  const fb = CART_FALLBACK[lang] || CART_FALLBACK.en;
  document.getElementById('cart-title').textContent = c.title || fb.title;
  const totalLbl = document.getElementById('cart-total-label-text');
  if(totalLbl) totalLbl.textContent = String(c.total || fb.total).replace(/\s*:\s*$/, '');
  document.getElementById('cart-order-label').textContent = c.orderVia;
  const body = document.getElementById('cart-items');
  if(cart.length === 0){
    body.innerHTML = `<div class="cart-empty">${c.empty}</div>`;
    document.getElementById('cart-footer').style.display = 'none';
    return;
  }
  document.getElementById('cart-footer').style.display = '';
  const phName = {ru:'Ваше имя',en:'Your name',es:'Tu nombre',cs:'Vaše jméno',uk:'Ваше імʼя'};
  const phContact = {ru:'Телефон или @ник в Telegram',en:'Phone or Telegram @username',es:'Teléfono o @usuario de Telegram',cs:'Telefon nebo @uživatel',uk:'Телефон або @нік у Telegram'};
  document.getElementById('cart-name').placeholder = phName[lang]||phName.en;
  document.getElementById('cart-contact').placeholder = phContact[lang]||phContact.en;
  body.innerHTML = cart.map(item=>`
    <div class="cart-item">
      <div class="cart-item-info">
        <div class="cart-item-title">${item.title}</div>
        <div class="cart-item-price">${item.price}</div>
      </div>
      <button class="cart-item-remove" data-id="${item.id}" aria-label="remove">×</button>
    </div>`).join('');
  document.getElementById('cart-total-val').textContent = cartTotalText();
  document.getElementById('cart-order-label').textContent = c.orderVia;

  const msg = buildOrderMessage(lang);
  const waUrl = `https://wa.me/${CONTACT_NUMBER}?text=${encodeURIComponent(msg)}`;
  const tgUrl = `https://t.me/+${CONTACT_NUMBER}`;

  const waBtn = document.getElementById('cart-wa-btn');
  waBtn.textContent = c.whatsapp;
  waBtn.href = waUrl;

  const tgBtn = document.getElementById('cart-tg-btn');
  tgBtn.textContent = c.telegram;
  tgBtn.href = tgUrl;
}

