function renderLaserPriceBody(L, P){
  const prRows = arr => arr.map(r=>`<div class="lm-price-row"><span class="lm-pr-lbl">${r.label}</span><span class="lm-pr-val">${r.was?`<span class="lm-pr-was">${r.was}</span>`:''} ${r.now||r.price}</span></div>`).join('');
  const pkgNote = L.packagesNote?`<p style="font-size:13px;color:var(--gold-dark);margin:-2px 0 12px;font-weight:500">${L.packagesNote}</p>`:'';
  if(laserPriceTab==='prague'){
    if(laserPriceSubTab==='women') return prRows(P.laserWomen.map(r=>({label:r.label,price:r.price+' Kč'})));
    if(laserPriceSubTab==='men') return prRows(P.laserMen.map(r=>({label:r.label,price:r.price+' Kč'})));
    return pkgNote + prRows(P.complexes.map(r=>({label:r.label,was:r.was+' Kč',now:r.now+' Kč'})));
  } else {
    if(laserPriceSubTab==='women') return prRows(L.laserWomenEs);
    if(laserPriceSubTab==='men') return prRows(L.laserMenEs);
    return pkgNote + prRows(L.complexesEs);
  }
}

