let svcPriceTab = 0;
function renderSvcPriceBody(groups){
  const g = groups[svcPriceTab] || groups[0];
  let html = (g.paras||[]).map(p=>`<p>${p}</p>`).join('');
  html += (g.rows||[]).map(r=>`<div class="lm-price-row"><span class="lm-pr-lbl">${r.label}</span><span class="lm-pr-val">${r.price}</span></div>`).join('');
  return html;
}
function renderServiceModal(key){
  const _t=window._SP_T;const D=(_t&&currentLang&&_t[currentLang]&&_t[currentLang][key])||(_t&&_t.cs&&_t.cs[key])||SERVICE_PAGES[key];
  if(!D) return;
  svcPriceTab = 0;
  const inner = document.getElementById('laser-modal-inner');
  const sectionsHtml = (D.sections||[]).map(sec=>{
    let body = '';
    if(sec.paras) body += sec.paras.map(p=>`<p>${p}</p>`).join('');
    if(sec.steps) body += `<ol class="lm-steps">${sec.steps.map(s=>`<li>${s}</li>`).join('')}</ol>`;
    if(sec.cols) body += `<div class="lm-cols">${sec.cols.map(c=>`<div class="lm-box"><h4>${c.title}</h4><ul>${c.list.map(li=>`<li>${li}</li>`).join('')}</ul></div>`).join('')}</div>`;
    if(sec.list) body += `<ul${sec.twoCol?' style="columns:2;gap:20px"':''}>${sec.list.map(li=>`<li>${li}</li>`).join('')}</ul>`;
    if(sec.note) body += `<div class="lm-note">${sec.note}</div>`;
    return `<div class="lm-section">${sec.title?`<h3>${sec.title}</h3>`:''}${body}</div>`;
  }).join('');
  const equipHtml = (D.equipment && D.equipment.length) ? `
    <div class="lm-section">
      <h3>${D.equipmentTitle||'Оборудование'}</h3>
      ${D.equipment.map(e=>`<div class="lm-eq"><div class="lm-eq-name">${e.name}</div><p>${e.desc}</p></div>`).join('')}
    </div>` : '';
  const faqHtml = (D.faq && D.faq.length) ? `
    <div class="lm-section">
      <h3>${D.faqTitle||'Частые вопросы'}</h3>
      <div id="lm-sfaq">${D.faq.map((item,i)=>`
        <div class="lm-faq-item">
          <button class="lm-faq-q" data-sfaq="${i}"><span>${item.q}</span><span class="lm-faq-icon" id="sfaq-icon-${i}">+</span></button>
          <div class="lm-faq-a" id="sfaq-ans-${i}">${item.a}</div>
        </div>`).join('')}</div>
    </div>` : '';
  const priceHtml = (D.priceGroups && D.priceGroups.length) ? `
    <div class="lm-section lm-price-section">
      <h3>Прайс</h3>
      ${D.priceGroups.length>1 ? `<div class="lm-price-tabs">${D.priceGroups.map((g,i)=>`<button data-svctab="${i}" class="${i===svcPriceTab?'active':''}">${g.title}</button>`).join('')}</div>` : `<div style="font-size:13px;color:var(--gold-dark);font-weight:500;margin-bottom:10px">${D.priceGroups[0].title}</div>`}
      <div id="svc-price-body">${renderSvcPriceBody(D.priceGroups)}</div>
    </div>` : '';
  const noteHtml = D.note ? `<div class="lm-section"><p style="color:var(--muted);font-style:italic">${D.note}</p></div>` : '';
  const consultHtml = `<div class="lm-consult"><h4>Бесплатная консультация</h4><p>Чтобы подобрать процедуру и метод именно для вас, приглашаем на бесплатную консультацию специалиста.</p></div>`;
  inner.innerHTML = `
    <div class="lm-hero">
      <span class="eyebrow">Hi Sisters Clinic</span>
      <h2>${D.title}</h2>
      <p>${D.intro}</p>
    </div>
    ${sectionsHtml}
    ${equipHtml}
    ${faqHtml}
    ${priceHtml}
    ${noteHtml}
    ${consultHtml}`;
  inner.querySelectorAll('[data-svctab]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      svcPriceTab = parseInt(btn.dataset.svctab);
      inner.querySelectorAll('[data-svctab]').forEach(b=>b.classList.toggle('active', parseInt(b.dataset.svctab)===svcPriceTab));
      document.getElementById('svc-price-body').innerHTML = renderSvcPriceBody(D.priceGroups);
    });
  });
  inner.querySelectorAll('.lm-faq-q[data-sfaq]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const i = btn.dataset.sfaq;
      const ans = document.getElementById('sfaq-ans-'+i);
      const icon = document.getElementById('sfaq-icon-'+i);
      const isOpen = ans.classList.contains('open');
      inner.querySelectorAll('.lm-faq-a').forEach(a=>a.classList.remove('open'));
      inner.querySelectorAll('.lm-faq-icon').forEach(ic=>{ic.classList.remove('open');ic.textContent='+';});
      if(!isOpen){ans.classList.add('open');icon.classList.add('open');icon.textContent='–';}
    });
  });
}

function openServiceModal(key){
  renderServiceModal(key);
  document.getElementById('laser-modal').classList.remove('hidden');
}


function openLaserModal(){
  renderLaserModal(currentLang);
  document.getElementById('laser-modal').classList.remove('hidden');
}
function closeLaserModal(){
  document.getElementById('laser-modal').classList.add('hidden');
}
document.getElementById('laser-modal-close').addEventListener('click', closeLaserModal);
document.getElementById('laser-modal-backdrop').addEventListener('click', closeLaserModal);
document.addEventListener('keydown', (e)=>{
  if(e.key==='Escape') closeLaserModal();
});
document.getElementById('services-grid').addEventListener('click', (e)=>{
  if(e.target.closest('[data-laser-detail]')) openLaserModal();
  var __sd = e.target.closest('[data-service-detail]'); if(__sd) openServiceModal(__sd.dataset.serviceDetail);
});
document.getElementById('cart-btn').addEventListener('click', ()=>{ openCart(); renderCartDrawer(currentLang); });
document.getElementById('cart-close').addEventListener('click', closeCart);
document.getElementById('cart-wa-btn').addEventListener('click', ()=>{ refreshOrderLinks(); notifyManager(currentLang, 'WhatsApp'); });
document.getElementById('cart-tg-btn').addEventListener('click', ()=> notifyManager(currentLang, 'Telegram'));
document.getElementById('rev-prev').addEventListener('click', ()=> scrollReviews(-1));
document.getElementById('rev-next').addEventListener('click', ()=> scrollReviews(1));
document.getElementById('svc-prev').addEventListener('click', ()=> scrollServices(-1));
document.getElementById('svc-next').addEventListener('click', ()=> scrollServices(1));
document.getElementById('cart-overlay').addEventListener('click', closeCart);

document.getElementById('cart-items').addEventListener('click', (e)=>{
  const btn = e.target.closest('.cart-item-remove');
  if(!btn) return;
  cartRemove(btn.dataset.id);
});

document.getElementById('training-list').addEventListener('click', (e)=>{
  const btn = e.target.closest('.cart-add-btn');
  if(!btn || btn.dataset.inCart === '1') return;
  cartAdd(btn.dataset.id, btn.dataset.title, btn.dataset.price);
  openCart();
  renderCartDrawer(currentLang);
});

function updateTrainingButtons(lang){
  const c = translations[lang].cart;
  document.querySelectorAll('.t-row[data-course-id]').forEach(row=>{
    const id = row.dataset.courseId;
    const btn = row.querySelector('.cart-add-btn');
    if(!btn) return;
    const inCart = cartIncludes(id);
    btn.textContent = inCart ? c.addedBtn : c.addBtn;
    btn.classList.toggle('in-cart', inCart);
    btn.dataset.inCart = inCart ? '1' : '';
  });
}

function renderTraining(lang){
  const list = document.getElementById('training-list');
  list.innerHTML = '';
  const c = translations[lang].cart;

  /* Courses are rendered with the very same markup as the services block
     (.s-card in a .svc-track carousel) so the two sections read as one system.
     COURSE_VISIBLE / COURSE_DETAILS live in the block at the end of the file. */
  const visible = (typeof COURSE_VISIBLE !== 'undefined') ? COURSE_VISIBLE : null;
  const imgs = (typeof COURSE_IMAGES !== 'undefined') ? COURSE_IMAGES : {};
  const ui = (typeof COURSE_UI !== 'undefined') ? (COURSE_UI[lang] || COURSE_UI.en) : {prog:''};

  const items = translations[lang].training.items.filter(t => !visible || visible.indexOf(t.id) >= 0);

  items.forEach((t, i) => {
    const card = document.createElement('div');
    card.className = 's-card';
    card.dataset.courseId = t.id;

    const bg = imgs[t.id]
      ? `background-image:url('${imgs[t.id]}')`
      : 'background-image:linear-gradient(160deg,#1E1670,#0A0738)';

    const hasDetail = (typeof COURSE_DETAILS !== 'undefined') && COURSE_DETAILS[t.id];
    const detailBtn = hasDetail
      ? `<button class="s-btn-detail" data-course-detail="${t.id}">${ui.prog}</button>`
      : '';

    const inCart = cartIncludes(t.id);
    const buyBtn = t.price
      ? `<button class="s-btn-price cart-add-btn${inCart ? ' in-cart' : ''}" data-id="${t.id}" data-title="${String(t.title).replace(/"/g,'&quot;')}" data-price="${t.price}" data-in-cart="${inCart ? '1' : ''}">${inCart ? c.addedBtn : c.addBtn}</button>`
      : '';

    card.innerHTML = `
      <div class="s-card-media" style="${bg};background-position:center 28%"></div>
      <div class="s-card-inner">
        <span class="num">0${i + 1}</span>
        <h3>${t.title}</h3>
        <p>${t.desc}</p>
        <div class="c-meta">
          <span class="c-format">${t.format || ''}</span>
          ${t.price ? `<span class="c-price">${t.price}</span>` : ''}
        </div>
        <div class="s-card-btns">
          ${buyBtn}
          ${detailBtn}
        </div>
      </div>`;
    list.appendChild(card);
  });
}
