function renderTeam(lang){
  const grid = document.getElementById('team-grid');
  grid.innerHTML = '';
  const members = currentCountry === 'spain' ? TEAM.filter(m=>m.photo==='anna') : TEAM;
  grid.classList.toggle('solo', members.length === 1);
  members.forEach(m=>{
    const name = m.name[lang] || m.name.en;
    const role = m.role[lang] || m.role.en;
    const desc = m.desc[lang] || m.desc.en;
    const card = document.createElement('div');
    card.className = 'team-card';
    /* A member can be added before their photo file exists — show an initial
       instead of a broken image until the file lands in assets/. */
    const src = teamPhotos[m.photo];
    const ph = src
      ? `<div class="ph"><img src="${src}" alt="${name}" loading="lazy" decoding="async"></div>`
      : `<div class="ph ph-init"><span>${name.trim().charAt(0)}</span></div>`;
    card.innerHTML = `${ph}<div class="name">${name}</div><div class="role">${role}</div><div class="bio">${desc}</div>`;
    grid.appendChild(card);
  });
}

