function renderReviews(lang){
  const head = REVIEWS_HEAD[lang]||REVIEWS_HEAD.en;
  const eb=document.getElementById('rev-eyebrow'), tt=document.getElementById('rev-title');
  if(eb) eb.textContent=head.eyebrow;
  if(tt) tt.textContent=head.title;
  const trustT=document.getElementById('rev-trust-text'); if(trustT) trustT.textContent=head.trust;
  const trustL=document.getElementById('rev-trust'); if(trustL) trustL.href=GOOGLE_URL;
  const track=document.getElementById('rev-track');
  if(!track) return;
  track.innerHTML='';
  (REVIEWS[lang] || REVIEWS.ru).forEach(r=>{
    const d=document.createElement('div'); d.className='rev-card';
    d.innerHTML=`<div class="rev-quote">&#8220;</div><div class="rev-stars">&#9733;&#9733;&#9733;&#9733;&#9733;</div><p class="rev-text">${r.q}</p><div class="rev-name">${r.name}</div><a class="rev-tag" href="${GOOGLE_URL}" target="_blank" rel="noopener">${head.tag} &#8599;</a>`;
    track.appendChild(d);
  });
}
/* Both carousels use scroll-snap-type: x mandatory. Chrome then ignores a
   programmatic scrollBy on them, so the arrow buttons did nothing at all.
   Lift the snap for the duration of the scroll and put it back after. */
function snapFreeScroll(t, dx){
  clearTimeout(t._snapRestore);
  t.style.scrollSnapType = 'none';
  t.style.scrollBehavior = 'auto';
  void t.offsetWidth;                 /* force the new styles to take effect */
  t.scrollLeft = t.scrollLeft + dx;   /* direct assignment; scrollBy is ignored while snapping */
  t._snapRestore = setTimeout(function(){
    t.style.removeProperty('scroll-snap-type');
    t.style.removeProperty('scroll-behavior');
  }, 80);
}
function scrollServices(dir){
  const t=document.getElementById('services-grid');
  if(!t) return;
  const card=t.querySelector('.s-card');
  const dx=(card?card.offsetWidth:340)+24;
  snapFreeScroll(t, dir*dx);
}
function scrollReviews(dir){
  const t=document.getElementById('rev-track');
  if(!t) return;
  const card=t.querySelector('.rev-card');
  const dx=(card?card.offsetWidth:360)+22;
  snapFreeScroll(t, dir*dx);
}

