const BOOKING_URL = 'https://cbox.mobi/go/hi-sisters?utm_source=website&utm_medium=site&utm_content=online_booking';

function openBooking(){
  const modal = document.getElementById('booking-modal');
  const iframe = document.getElementById('booking-iframe');
  const loading = document.getElementById('booking-loading');
  // Lazy-load the iframe src only once
  if(!iframe.src || iframe.src === window.location.href){
    loading.classList.remove('hidden');
    iframe.src = BOOKING_URL;
    iframe.onload = () => loading.classList.add('hidden');
  }
  modal.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  // Update title per current language
  const lang = currentLang;
  const titles = {ru:'Онлайн-запись',en:'Book online',es:'Reservar online',cs:'Rezervovat online',uk:'Онлайн-запис'};
  document.getElementById('booking-modal-title').textContent = titles[lang] || 'Book online';
  const footT={ru:'Не открывается форма?',en:"Form won't load?",es:'¿No carga el formulario?',cs:'Formulář se nenačítá?',uk:'Не відкривається форма?'};
  const footL={ru:'Открыть запись в новой вкладке',en:'Open booking in a new tab',es:'Abrir reserva en otra pestaña',cs:'Otevřít rezervaci v nové kartě',uk:'Відкрити запис у новій вкладці'};
  const ft=document.getElementById('booking-foot-text'); if(ft) ft.textContent=footT[lang]||footT.ru;
  const fl=document.getElementById('booking-foot-link'); if(fl) fl.textContent=footL[lang]||footL.ru;
}

function closeBooking(){
  document.getElementById('booking-modal').classList.add('hidden');
  document.body.style.overflow = '';
}

