// Lazy-load the embedded CBox calendar only when the section scrolls into view
(function(){
  const wrap = document.querySelector('.bk-embed');
  if(!wrap) return;
  const iframe = document.getElementById('bk-embed-iframe');
  const loading = document.getElementById('bk-embed-loading');
  const load = ()=>{
    if(iframe.src && iframe.src !== window.location.href) return;
    iframe.src = iframe.dataset.src;
    iframe.onload = ()=> loading.classList.add('hidden');
  };
  if('IntersectionObserver' in window){
    const obs = new IntersectionObserver((entries)=>{
      entries.forEach(en=>{ if(en.isIntersecting){ load(); obs.disconnect(); } });
    }, {rootMargin:'300px'});
    obs.observe(wrap);
  } else {
    load();
  }
})();

