  var faq='<section class="faq-section" id="faq"><div class="faq-inner"><p class="faq-label">'+d.fl+'</p><h2 class="faq-title">'+d.ft+'</h2>'+d.faqs.map(function(f){return'<div class="faq-item"><button class="faq-q"><span class="faq-q-text">'+f.q+'</span><span class="faq-icon">+</span></button><div class="faq-a"><div class="faq-a-inner">'+f.a+'</div></div></div>';}).join('')+'</div></section>';
