// Also watch for visibility changes
document.addEventListener('visibilitychange',function(){if(!document.hidden)setTimeout(injectGallery,500);});

// Fallback interval - retry every 2s up to 30s
var _gIv=setInterval(function(){
  if(injectGallery()!==undefined||++window._gTries>15)clearInterval(_gIv);
},2000);
window._gTries=0;

