(function(){
  /* Four real accounts, one per language/city. Send people to the one they can
     actually read: Czech page -> @hi.sisters_cz, Spanish -> @hi.sisters_vlc,
     everything else -> @hi.sisters.clinic (the main, largest account). */
  var ACC = {
    czech: {cs:'hi.sisters_cz', _:'hi.sisters.clinic'},
    spain: {es:'hi.sisters_vlc', _:'hi.sisters_valencia'}
  };
  function pick(){
    var country = 'czech';
    try{ country = localStorage.getItem('hs-country') === 'spain' ? 'spain' : 'czech'; }catch(e){}
    var lang = (document.documentElement.lang || 'cs').slice(0,2);
    var set = ACC[country] || ACC.czech;
    return set[lang] || set._;
  }
  function sync(){
    var h = pick();
    document.querySelectorAll('a.nav-soc.ig, a.social-link.ig').forEach(function(a){
      a.href = 'https://www.instagram.com/' + h + '/';
      a.title = '@' + h;
    });
  }
  sync();
  new MutationObserver(sync).observe(document.documentElement, {attributes:true, attributeFilter:['lang']});
  document.addEventListener('click', function(e){
    if(e.target.closest('[data-country]')) setTimeout(sync, 60);
  }, true);
})()
;

