const COURSE_UI = {"ru": {"prog": "Программа курса", "close": "Закрыть"}, "uk": {"prog": "Програма курсу", "close": "Закрити"}, "cs": {"prog": "Program kurzu", "close": "Zavřít"}, "en": {"prog": "Course programme", "close": "Close"}, "es": {"prog": "Programa del curso", "close": "Cerrar"}};
const COURSE_VISIBLE = ["laser-basic", "laser-adv", "electro-start", "electro-full", "electro-adv"];
const COURSE_IMAGES = {"laser-basic": "assets/trainer-laser.jpg", "laser-adv": "assets/trainer-laser.jpg", "electro-start": "assets/trainer-electro.jpg", "electro-full": "assets/trainer-electro.jpg", "electro-adv": "assets/trainer-electro.jpg"};
(function(){
  function esc(x){ return String(x == null ? '' : x).replace(/[&<>"]/g, function(ch){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch];
  }); }

  function findItem(lang, id){
    try{ return (translations[lang].training.items || []).filter(function(t){ return t.id === id; })[0] || null; }
    catch(e){ return null; }
  }

  function openCourse(id){
    var lang = (document.documentElement.lang || 'cs').slice(0,2);
    var d = COURSE_DETAILS[id] && (COURSE_DETAILS[id][lang] || COURSE_DETAILS[id].en);
    if(!d) return;
    var t = findItem(lang, id) || {};
    var html = '<h3>' + esc(t.title || '') + '</h3>';
    if(t.format) html += '<div class="cm-sub">' + esc(t.format) + '</div>';
    html += '<div class="cm-lead">' + esc(d.lead) + '</div>';
    d.groups.forEach(function(g){
      html += '<h4>' + esc(g[0]) + '</h4><ul>';
      g[1].forEach(function(li){ html += '<li>' + esc(li) + '</li>'; });
      html += '</ul>';
    });
    if(t.price) html += '<div class="cm-price">' + esc(t.price) + '</div>';
    document.getElementById('cm-body').innerHTML = html;
    document.getElementById('cm-back').classList.add('open');
  }
  function closeCourse(){
    document.getElementById('cm-back').classList.remove('open');
  }

  document.addEventListener('click', function(e){
    var b = e.target.closest('[data-course-detail]');
    if(b){ e.preventDefault(); openCourse(b.dataset.courseDetail); return; }
    if(e.target.id === 'cm-x' || e.target.id === 'cm-back') closeCourse();
  });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeCourse(); });

  /* Arrows for the course carousel, same helper the services carousel uses. */
  function scrollTraining(dir){
    var t = document.getElementById('training-list');
    if(!t) return;
    var card = t.querySelector('.s-card');
    var dx = (card ? card.offsetWidth : 340) + 14;
    if(typeof snapFreeScroll === 'function') snapFreeScroll(t, dir * dx);
    else t.scrollLeft += dir * dx;
  }
  function wire(){
    var p = document.getElementById('trn-prev'), n = document.getElementById('trn-next');
    if(p && !p._w){ p._w = 1; p.addEventListener('click', function(){ scrollTraining(-1); }); }
    if(n && !n._w){ n._w = 1; n.addEventListener('click', function(){ scrollTraining(1); }); }
  }
  wire();
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', wire);

  /* renderTraining already ran once before this block executed, so the very
     first paint had no access to COURSE_VISIBLE/COURSE_DETAILS. Redraw once. */
  function redraw(){
    try{ renderTraining(typeof currentLang !== 'undefined' ? currentLang : 'cs'); wire(); }catch(e){}
  }
  redraw();
  setTimeout(redraw, 400);
})();

;

