function esc(x){return String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function render(){
  var sec=document.getElementById('homecare'); if(!sec) return;
  try{ if(localStorage.getItem('hs-country')==='spain'){ sec.style.display='none'; return; } sec.style.display=''; }catch(e){}
  var L=document.documentElement.lang||'ru'; if(!T[L]) L='ru';
  var t=T[L];
  var ids={'hc-eyebrow':t.eyebrow,'hc-title':t.title,'hc-subtitle':t.subtitle,'hc-note':t.note,'hc-cta':t.cta};
  for(var id in ids){ var el=document.getElementById(id); if(el) el.textContent=ids[id]; }
  var grid=document.getElementById('homecare-grid'); if(!grid) return;
  var html='';
  ['loss','scalp','care'].forEach(function(cat){
    html+='<div class="hc-cat">'+esc(t.cats[cat])+'</div><div class="hc-row">';
    P.filter(function(p){return p.c===cat;}).forEach(function(p){
      html+='<div class="hc-card"><div class="hc-brand">'+esc(p.b)+'</div><div class="hc-name">'+esc(p.n)+'</div><div class="hc-desc">'+esc(p.d[L]||p.d.ru)+'</div><div class="hc-price">'+p.p+' Kč<span class="hc-vol">'+esc(p.v)+'</span></div></div>';
    });
    html+='</div>';
  });
  grid.innerHTML=html;
}
new MutationObserver(function(){try{render()}catch(e){}}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
