/* ============================================================
   Multi-page additions: detail renderers for services.html and
   training.html. Content comes from the same translations /
   _SP_T / COURSE_DETAILS objects the modals use, so the pages
   stay in sync with the rest of the site automatically.
   ============================================================ */
(function(){
  var PAGE = document.body.dataset.page || 'home';
  if(PAGE !== 'services' && PAGE !== 'training') return;

  var css = document.createElement('style');
  css.textContent = '.dt-article details{margin-bottom:8px;border:1px solid var(--cream-deep);border-radius:6px;padding:10px 14px;}'
    + '.dt-article summary{cursor:pointer;font-size:14.5px;color:var(--navy);font-weight:500;}'
    + '.dt-article details p{margin:8px 0 2px;font-size:14px;color:var(--ink);line-height:1.55;}'
    + '.dt-article .dt-was{color:var(--muted);text-decoration:line-through;margin-right:8px;font-size:13px;}';
  document.head.appendChild(css);

  function esc(x){ return String(x==null?'':x).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }

  function secHtml(sec){
    var b='';
    if(sec.paras) b+=sec.paras.map(function(p){return '<p class="dt-lead">'+p+'</p>';}).join('');
    if(sec.steps) b+='<ul>'+sec.steps.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul>';
    if(sec.cols) b+=sec.cols.map(function(c){return '<h3>'+esc(c.title)+'</h3><ul>'+c.list.map(function(li){return '<li>'+li+'</li>';}).join('')+'</ul>';}).join('');
    if(sec.list) b+='<ul>'+sec.list.map(function(li){return '<li>'+li+'</li>';}).join('')+'</ul>';
    if(sec.note) b+='<p class="dt-lead" style="font-style:italic;color:var(--muted)">'+sec.note+'</p>';
    return (sec.title?'<h3>'+esc(sec.title)+'</h3>':'')+b;
  }
  function faqHtml(title, faq){
    if(!faq || !faq.length) return '';
    return '<h3>'+esc(title||'FAQ')+'</h3>'+faq.map(function(f){
      return '<details><summary>'+esc(f.q)+'</summary><p>'+f.a+'</p></details>';}).join('');
  }
  function bookBtn(lang){
    var t={cs:'Rezervovat konzultaci',ru:'Записаться на консультацию',uk:'Записатися на консультацію',en:'Book a consultation',es:'Reservar consulta'};
    return '<a href="#" data-book="1" class="dt-btn">'+ (t[lang]||t.en) +'</a>';
  }

  /* ---------------- services.html ---------------- */
  function renderServiceDetails(lang){
    var wrap=document.getElementById('svc-details-wrap');
    if(!wrap) return;
    var sect=document.getElementById('svc-details'); if(sect) sect.style.display='';
    var sv=(translations[lang]&&translations[lang].services)||{};
    var items=sv.items||{}; /* may not exist; fall back to card titles */
    var out='';

    /* laser first: services.items.laser + services.laserPage + services.pricing */
    var items2=sv.items||{};
    var laser=items2.laser||{}; var L=sv.laserPage||{}; var P=sv.pricing||{};
    function block(title,val){
      if(!val) return '';
      var b='<h3>'+esc(title||'')+'</h3>';
      if(Array.isArray(val)) b+='<ul>'+val.map(function(x){return '<li>'+(typeof x==='string'?x:esc(JSON.stringify(x)))+'</li>';}).join('')+'</ul>';
      else b+='<p class="dt-lead">'+val+'</p>';
      return b;
    }
    function priceList(title,rows){
      if(!rows||!rows.length) return '';
      return '<h3>'+esc(title||'')+'</h3><ul>'+rows.map(function(r){
        if(r.now!=null) return '<li>'+esc(r.label)+' — <span class="dt-was">'+r.was+' Kč</span><b>'+r.now+' Kč</b></li>';
        return '<li>'+esc(r.label)+' — <b>'+r.price+' Kč</b></li>';}).join('')+'</ul>';
    }
    var body='';
    if(L.intro) body+='<p class="dt-lead">'+L.intro+'</p>';
    else if(laser.desc) body+='<p class="dt-lead">'+esc(laser.desc)+'</p>';
    body+=block(L.howTitle, L.how);
    body+=block(L.guaranteeTitle, L.guarantee);
    body+=block(L.whoTitle, L.who);
    body+=block(L.contraTitle, L.contra);
    body+=priceList(P.tabComplexes, P.complexes);
    body+=priceList((P.tabWomen||'')+(L.womenLabel?'':''), P.laserWomen);
    body+=priceList(P.tabMen, P.laserMen);
    if(P.pragueNote) body+='<p class="dt-lead" style="color:var(--muted);font-size:13px">'+esc(P.pragueNote)+'</p>';
    body+=faqHtml(L.faqTitle||'FAQ', L.faq);
    out+='<article class="dt-article" id="svc-laser"><h2>'+esc(laser.title||'Laser')+'</h2>'+body
       +'<div class="dt-actions">'+bookBtn(lang)+'</div></article>';

    /* the rest come from _SP_T (same source as the service modals) */
    var T=(window._SP_T&&(window._SP_T[lang]||window._SP_T.cs))||{};
    ['electro','peeling','massage','cosmetology','trichology'].forEach(function(key){
      var D=T[key]; if(!D) return;
      var body='';
      if(D.intro) body+='<p class="dt-lead">'+D.intro+'</p>';
      (D.sections||[]).forEach(function(s){ body+=secHtml(s); });
      if(D.equipment&&D.equipment.length){ body+='<h3>'+esc(D.equipmentTitle||'')+'</h3><ul>'+D.equipment.map(function(e){return '<li><b>'+esc(e.name)+'</b> — '+e.desc+'</li>';}).join('')+'</ul>'; }
      (D.priceGroups||[]).forEach(function(g){ body+='<h3>'+esc(g.title)+'</h3>'+(g.paras||[]).map(function(p){return '<p class="dt-lead">'+p+'</p>';}).join(''); });
      body+=faqHtml(D.faqTitle, D.faq);
      if(D.note) body+='<p class="dt-lead" style="font-style:italic;color:var(--muted)">'+D.note+'</p>';
      out+='<article class="dt-article" id="svc-'+key+'"><h2>'+esc(D.title)+'</h2>'+body
         +'<div class="dt-actions">'+bookBtn(lang)+'</div></article>';
    });
    wrap.innerHTML=out;
  }

  /* ---------------- training.html ---------------- */
  function renderCourseDetails(lang){
    var wrap=document.getElementById('course-details-wrap');
    if(!wrap) return;
    var sect=document.getElementById('course-details'); if(sect) sect.style.display='';
    var items=((translations[lang]||{}).training||{}).items||[];
    var ui=(typeof COURSE_UI!=='undefined')?(COURSE_UI[lang]||COURSE_UI.en):{prog:''};
    var c=(translations[lang]||{}).cart||{};
    var visible=(typeof COURSE_VISIBLE!=='undefined')?COURSE_VISIBLE:null;
    var out='';
    items.filter(function(t){return !visible||visible.indexOf(t.id)>=0;}).forEach(function(t){
      var D=(typeof COURSE_DETAILS!=='undefined')&&COURSE_DETAILS[t.id]&&(COURSE_DETAILS[t.id][lang]||COURSE_DETAILS[t.id].en);
      var body='';
      if(D){ body+='<p class="dt-lead">'+esc(D.lead)+'</p>';
        D.groups.forEach(function(g){ body+='<h3>'+esc(g[0])+'</h3><ul>'+g[1].map(function(li){return '<li>'+esc(li)+'</li>';}).join('')+'</ul>'; }); }
      var inCart=(typeof cartIncludes==='function')&&cartIncludes(t.id);
      out+='<article class="dt-article" id="course-'+esc(t.id)+'">'
         +'<h2>'+esc(t.title)+'</h2><div class="dt-sub">'+esc(t.format||'')+'</div>'+body
         +'<div class="dt-actions"><span class="dt-price">'+esc(t.price||'')+'</span>'
         +(t.price?'<button class="dt-btn cart-add-btn'+(inCart?' in-cart':'')+'" data-id="'+esc(t.id)+'" data-title="'+esc(t.title)+'" data-price="'+esc(t.price)+'" data-in-cart="'+(inCart?'1':'')+'">'+(inCart?(c.addedBtn||'✓'):(c.addBtn||'+'))+'</button>':'')
         +bookBtn(lang).replace('dt-btn','dt-btn alt')+'</div></article>';
    });
    wrap.innerHTML=out;
  }

  document.addEventListener('click', function(e){
    var btn=e.target.closest('#course-details .cart-add-btn');
    if(!btn||btn.dataset.inCart==='1') return;
    cartAdd(btn.dataset.id, btn.dataset.title, btn.dataset.price);
    btn.dataset.inCart='1';
    btn.textContent=((translations[currentLang]||{}).cart||{}).addedBtn||'✓';
    openCart(); renderCartDrawer(currentLang);
  });

  var last=null;
  function render(){
    var l=document.documentElement.lang||'cs';
    if(l===last) return; last=l;
    try{ if(PAGE==='services') renderServiceDetails(l); else renderCourseDetails(l); }catch(err){}
  }
  function boot(){ render(); setTimeout(function(){ last=null; render(); }, 600); }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', boot); else boot();
  new MutationObserver(function(){ render(); }).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
})();
